...[1,2,3,4,5].map(i=>({id:`wuyuan-${i}`,category:'painting',title:`婺源写生 · ${String(i).padStart(2,'0')}`,english:'WUYUAN / LANDSCAPE STUDIES',cover:`wuyuan-${i}.webp`,ratio:[0.975488, 0.748109, 0.800306, 0.846352, 1.34445][i-1],number:i,series:'wuyuan',seriesTitle:'婺源风景写生系列',meta:['风景写生','江西 · 婺源'],intro:'在江西婺源写生创作的风景系列。',images:[`wuyuan-${i}.webp`]})),
