const cards=works.map((work,i)=>{const el=document.createElement('button');el.className='art-card';el.setAttribute('aria-label',`${work.title}，${labels[work.category]}，打开作品`);el.innerHTML=`<img src="assets/${work.cover}" alt="${work.title}" draggable="false" fetchpriority="${i<2?'high':'auto'}">`;sphere.append(el);el.addEventListener('click',()=>{if(!moved)openWork(work.id)});el.addEventListener('pointerenter',()=>{hovered=i;showLabel(work)});el.addEventListener('pointerleave',()=>{hovered=null;if(focused===null)hideLabel()});el.addEventListener('focus',()=>{focused=i;showLabel(work)});el.addEventListener('blur',()=>{focused=null;if(hovered===null)hideLabel()});return{el,work,pos:{x:0,y:0,z:0},target:{x:0,y:0,z:0},visible:true}});
function showLabel(w){$('#hover-label').innerHTML=`${w.title}<small>${w.english}</small>`;$('#hover-label').style.opacity='1'}
function hideLabel(){$('#hover-label').style.opacity='0'}
function resize(){width=space.clientWidth;height=space.clientHeight}new ResizeObserver(resize).observe(space);resize();
function targets(){const visible=cards.filter(c=>filter==='all'||c.work.category===filter);visible.forEach((c,i)=>{const n=visible.length;if(n===1)c.target={x:0,y:0,z:.45};else{const y=1-2*(i+.5)/n;const r=Math.sqrt(1-y*y),theta=i*Math.PI*(3-Math.sqrt(5))+.38;c.target={x:Math.cos(theta)*r,y:y*.91,z:Math.sin(theta)*r}}});cards.forEach(c=>{c.visible=visible.includes(c);c.el.style.opacity=c.visible?'1':'0';c.el.style.pointerEvents=c.visible?'':'none';c.el.tabIndex=c.visible?0:-1;c.el.setAttribute('aria-hidden',String(!c.visible))});$('#index-count').textContent=`01 — ${String(visible.length).padStart(2,'0')}`;return visible}
function animate(t){const dt=Math.min((t-lastTime)/16.667||1,3);lastTime=t;const paused=gridMode||workDialog.open||aboutDialog.open;const visible=cards.filter(c=>c.visible);if(!paused){if(!dragging&&hovered===null&&focused===null){yaw+=vy*dt;pitch+=vp*dt;vy*=Math.pow(.92,dt);vp*=Math.pow(.92,dt);if(autoRotate&&visible.length>1)yaw+=.0016*dt}pitch=Math.max(-1.1,Math.min(1.1,pitch));const mobile=width<760;const rx=Math.min(width*(mobile?.28:.31),440),ry=mobile?Math.max(70,(height-170)*.34):Math.min(height*.36,285);const cx=width*(mobile?.5:.55),cy=mobile?(height+100)/2:height*.51;cards.forEach(c=>{['x','y','z'].forEach(k=>c.pos[k]+=(c.target[k]-c.pos[k])*(reduceMotion?1:.09));let {x,y,z}=c.pos;if(visible.length>1){let nx=x*Math.cos(yaw)+z*Math.sin(yaw);z=-x*Math.sin(yaw)+z*Math.cos(yaw);x=nx;let ny=y*Math.cos(pitch)-z*Math.sin(pitch);z=y*Math.sin(pitch)+z*Math.cos(pitch);y=ny}const perspective=1/(1-z*.27);const density=visible.length>8?(mobile?.72:.82):1;const baseWidth=(c.work.category==='design'?(mobile?151:230):Math.min(mobile?122:195,(mobile?89:140)*Math.sqrt(c.work.ratio/.74)))*density;const w=visible.length===1?Math.min(width*(mobile?.49:.28),c.work.category==='design'?420:245):baseWidth*perspective;const h=w/c.work.ratio;c.el.style.width=`${w}px`;c.el.style.transform=`translate3d(${cx-width/2+x*rx*perspective-w/2}px,${cy-height/2-y*ry*perspective-h/2}px,0)`;c.el.style.zIndex=String(Math.round((z+2)*100));c.el.style.filter=z<-.3?'brightness(.96)':'none'})}frame=requestAnimationFrame(animate)}
targets();cards.forEach(c=>c.pos={...c.target});frame=requestAnimationFrame(animate);
function updateMotion(){const b=$('#motion-toggle');b.textContent=autoRotate?'Ⅱ':'▷';b.setAttribute('aria-label',autoRotate?'暂停自动旋转':'开启自动旋转');b.title=b.getAttribute('aria-label')}
$('#motion-toggle').addEventListener('click',()=>{autoRotate=!autoRotate;vy=vp=0;updateMotion()});updateMotion();
sphere.addEventListener('pointerdown',e=>{if(e.button!==0)return;dragging=true;moved=false;lastX=startX=e.clientX;lastY=startY=e.clientY;vy=vp=0});
window.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;if(Math.hypot(e.clientX-startX,e.clientY-startY)>5){moved=true;autoRotate=false;updateMotion();hideLabel()}if(moved){vy=dx*.0045;vp=dy*.0035;yaw+=vy;pitch+=vp}lastX=e.clientX;lastY=e.clientY});
window.addEventListener('pointerup',()=>{dragging=false;setTimeout(()=>{moved=false},0)});window.addEventListener('pointercancel',()=>{dragging=false;moved=false});window.addEventListener('blur',()=>{dragging=false});
sphere.addEventListener('wheel',e=>{if(workDialog.open||aboutDialog.open)return;e.preventDefault();autoRotate=false;updateMotion();vy+=Math.max(-80,Math.min(80,e.deltaY))*.00055;pitch+=Math.max(-80,Math.min(80,e.deltaX))*.0003},{passive:false});
document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.filter;document.querySelectorAll('.filter').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});hovered=focused=null;hideLabel();yaw=.27;pitch=-.1;vy=vp=0;targets();renderGrid()}));
function renderGrid(){grid.innerHTML='';works.filter(w=>filter==='all'||w.category===filter).forEach(w=>{const b=document.createElement('button');b.className='grid-card';b.innerHTML=`<div class="grid-image"><img src="assets/${w.cover}" alt="${w.title}" loading="lazy"></div><div class="grid-caption">${w.title}<small>${labels[w.category]} ↗</small></div>`;b.addEventListener('click',()=>openWork(w.id));grid.append(b)})}renderGrid();
