function heading(w){return `<div class="work-heading"><span class="tiny-label">${w.english}</span><h2>${w.title}</h2><div class="work-meta">${w.meta.map(x=>`<span>${x}</span>`).join('')}</div>${w.intro?`<p class="work-intro">${w.intro}</p>`:''}</div>`}
