function openWork(id){const w=works.find(x=>x.id===id);if(!w)return;activeWork=id;let html='';if(w.category==='painting'){html=`<div class="painting-layout"><figure><img class="zoom-image" src="assets/${w.cover}" alt="${w.title}，油画" tabindex="0" role="button" aria-label="放大查看油画细节"></figure><div>${heading(w)}<p class="work-intro">${w.seriesTitle}<br>点击画面，查看笔触与细节。</p><div class="series-nav" aria-label="${w.seriesTitle}作品">${works.filter(x=>x.category==='painting'&&x.series===w.series).map(x=>`<button data-work="${x.id}" class="${x.id===id?'current':''}" aria-label="查看${x.title}" aria-pressed="${x.id===id}"><img src="assets/${x.cover}" alt=""></button>`).join('')}</div></div></div>`}else{html=heading(w)+`<div class="gallery">${w.video?`<figure><video controls playsinline preload="none" poster="assets/video-cover.webp" aria-label="美，是每天发生的事，AI 系列影像"><source src="assets/${w.video}" type="video/mp4">浏览器不支持视频播放。</video><figcaption>美，是每天发生的事 · 系列影像</figcaption></figure>`:''}${w.images.map((src,i)=>`<figure><img class="zoom-image" src="assets/${src}" alt="${w.title} — ${w.category==='ai'?captions[i]:`项目展示 ${i+1}`}" loading="lazy" tabindex="0" role="button" aria-label="放大查看${w.title}第${i+1}张图片">${w.category==='ai'?`<figcaption>${captions[i]}</figcaption>`:''}</figure>`).join('')}</div>`}html+=`<div class="work-end"><span>李煜 Kai · ${labels[w.category]}</span><button id="back-space">返回创意空间 ↗</button></div>`;$('#work-content').innerHTML=html;$('#work-content').querySelectorAll('[data-work]').forEach(b=>b.addEventListener('click',()=>openWork(b.dataset.work)));$('#work-content').querySelectorAll('.zoom-image').forEach(img=>{function toggle(){img.classList.toggle('is-zoomed');img.setAttribute('aria-label',img.classList.contains('is-zoomed')?'缩小图片':'放大查看图片')}img.addEventListener('click',toggle);img.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle()}})});$('#back-space').addEventListener('click',()=>workDialog.close());if(!workDialog.open){workDialog.showModal();document.body.style.overflow='hidden'}workDialog.scrollTop=0;$('#work-close').focus();}
$('#work-close').addEventListener('click',()=>workDialog.close());workDialog.addEventListener('close',()=>{workDialog.querySelectorAll('video').forEach(v=>v.pause());document.body.style.overflow='';activeWork=null});
$('#about-open').addEventListener('click',()=>{aboutDialog.showModal();document.body.style.overflow='hidden'});$('#about-close').addEventListener('click',()=>aboutDialog.close());aboutDialog.addEventListener('close',()=>{document.body.style.overflow=''});aboutDialog.addEventListener('click',e=>{const r=aboutDialog.getBoundingClientRect();if(e.target===aboutDialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))aboutDialog.close()});
